<?php
namespace App\Services;use App\Config\Database;use App\Services\Provider\CeirGoProvider;
final class OrderService{public function create(int $uid,int $pid,string $imei):array{if(!preg_match('/^\d{15}$/',$imei))throw new \InvalidArgumentException('IMEI harus tepat 15 digit angka');$db=Database::get();$oid=0;$db->beginTransaction();try{$q=$db->prepare('SELECT p.*,pp.price FROM products p JOIN users u ON u.id=? JOIN product_prices pp ON pp.product_id=p.id AND pp.level_id=u.level_id WHERE p.id=? AND p.is_active=1');$q->execute([$uid,$pid]);$p=$q->fetch();if(!$p)throw new \RuntimeException('Produk tidak tersedia');$no='ORD-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$db->prepare('INSERT INTO orders(order_number,user_id,product_id,imei,status,selling_price,provider_cost,provider_type,wa_group_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$no,$uid,$pid,$imei,'pending',$p['price'],$p['provider_cost'],$p['provider_type'],$p['whatsapp_group_id']]);$oid=(int)$db->lastInsertId();WalletService::move($db,$uid,-(float)$p['price'],'order',$no,'order:'.$oid);$db->commit();if((int)$p['ceir_check_enabled']===1){$c=(new CeirService())->check($imei);$db->prepare('UPDATE orders SET ceir_status=?,ceir_raw_response=?,status=? WHERE id=?')->execute([$c['status'],json_encode($c['raw']),$c['status']==='UNKNOWN'?'processing':'rejected',$oid]);if(in_array($c['status'],['REGISTERED','ROAMER','ERROR'],true)){(new RefundService())->refund($oid,'CEIR '.$c['status']);return $this->get($oid);}}if($p['provider_type']==='ceirgo'){$r=(new CeirGoProvider())->submit(['imei'=>$imei],$p);$db->prepare('UPDATE orders SET provider_order_id=?,provider_response=?,status=? WHERE id=?')->execute([(string)($r['order_id']??$r['reference_id']??''),json_encode($r),($r['status']??'pending')==='success'?'success':'processing',$oid]);}return $this->get($oid);}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();if($oid){try{(new RefundService())->refund($oid,'Processing error');}catch(\Throwable $ignored){}}throw $e;}}public function get(int $id):array{$q=Database::get()->prepare('SELECT * FROM orders WHERE id=?');$q->execute([$id]);return $q->fetch()?:[];}public function setStatus(int $id,string $status,string $reason=''):void{if(!in_array($status,['pending','processing','success','rejected','refunded','cancelled'],true))throw new \InvalidArgumentException('Status invalid');if($status==='rejected'){(new RefundService())->refund($id,$reason?:'Rejected');return;}Database::get()->prepare('UPDATE orders SET status=?,completed_at=IF(?="success",NOW(),completed_at) WHERE id=?')->execute([$status,$status,$id]);}}
